record Candidate(String name, int score, boolean reviewed) {}

List<Boolean> rules = List.of(
    !candidate.name().isBlank(),
    candidate.score() >= threshold, // seuil différent de l'exemple d'entraînement
    candidate.reviewed()
);

long passed = rules.stream().filter(Boolean::booleanValue).count();
if (passed != rules.size()) throw new AssertionError("critères non transférés au nouveau contexte");

